  package    org . cloudbus . cloudsim . lists ;   import   java . util . Collections ;  import   java . util . Comparator ;  import   java . util . List ;  import    org . cloudbus . cloudsim . Cloudlet ;   public class CloudletList  {   public static  <  T  extends Cloudlet > T getById  (   List  < T > cloudletList ,   int id )  {  for ( T cloudlet : cloudletList )  {  if  (   cloudlet . getCloudletId  ( ) == id )  {  return cloudlet ; } }  return null ; }   public static  <  T  extends Cloudlet >  int getPositionById  (   List  < T > cloudletList ,   int id )  {   int  i = 0 ;  for ( T cloudlet : cloudletList )  {  if  (   cloudlet . getCloudletId  ( ) == id )  {  return i ; }   i ++ ; }  return  - 1 ; }   public static  <  T  extends Cloudlet > void sort  (   List  < T > cloudletList )  {   Collections . sort  ( cloudletList ,  new  Comparator  < T >  ( )  {    @ Override public  int compare  (  T a ,  T b )  throws ClassCastException  {  Double  cla =  Double . valueOf  (  a . getCloudletTotalLength  ( ) ) ;  Double  clb =  Double . valueOf  (  b . getCloudletTotalLength  ( ) ) ;  return  cla . compareTo  ( clb ) ; } } ) ; } }